#!/bin/bash
# Start MCPJungle in enterprise mode and initialise it on first boot, so the
# deployment is locked from the start and needs no manual `mcpjungle init-server`.
#
#   MCPJUNGLE_ADMIN_TOKEN   admin access token (generated by the template)
#   MCPJUNGLE_CLIENT_TOKEN  bearer token of the "default" MCP client (generated by the template)
#   DATABASE_URL            Postgres connection string (reference to the Postgres service)
set -uo pipefail

log() { echo "[railway-start] $*"; }
die() { echo "[railway-start] ERROR: $*" >&2; exit 1; }

: "${DATABASE_URL:?DATABASE_URL must point at Postgres}"
ADMIN_TOKEN="${MCPJUNGLE_ADMIN_TOKEN:-}"
CLIENT_TOKEN="${MCPJUNGLE_CLIENT_TOKEN:-}"
CLIENT_NAME="${MCPJUNGLE_CLIENT_NAME:-default}"
[ "${#ADMIN_TOKEN}" -ge 16 ] || die "MCPJUNGLE_ADMIN_TOKEN must be set (at least 16 characters)"
[ "${#CLIENT_TOKEN}" -ge 16 ] || die "MCPJUNGLE_CLIENT_TOKEN must be set (at least 16 characters)"
case "$ADMIN_TOKEN$CLIENT_TOKEN" in *[[:space:]]*) die "tokens must not contain spaces";; esac
[ "$ADMIN_TOKEN" != "$CLIENT_TOKEN" ] || die "MCPJUNGLE_ADMIN_TOKEN and MCPJUNGLE_CLIENT_TOKEN must differ"

export PORT="${PORT:-8080}"
export SERVER_MODE=enterprise
# /metrics is public when telemetry is on, so it stays off unless you turn it on.
export OTEL_ENABLED="${OTEL_ENABLED:-false}"
export MCP_SERVER_INIT_REQ_TIMEOUT_SEC="${MCP_SERVER_INIT_REQ_TIMEOUT_SEC:-90}"
# Railway shows the host's CPUs inside a small service: keep Go's scheduler and heap modest.
export GOMAXPROCS="${GOMAXPROCS:-2}"
if [ -z "${GOMEMLIMIT:-}" ] && [ -r /sys/fs/cgroup/memory.max ]; then
  lim=$(cat /sys/fs/cgroup/memory.max)
  if [ "$lim" != "max" ]; then export GOMEMLIMIT="$(( lim * 6 / 10 / 1048576 ))MiB"; fi
fi

# Caches and a work folder for STDIO MCP servers (npx/uvx) live on the volume.
DATA_DIR="${MCPJUNGLE_DATA_DIR:-/data}"
mkdir -p "$DATA_DIR/npm-cache" "$DATA_DIR/uv-cache" "$DATA_DIR/workspace" 2>/dev/null || true
export npm_config_cache="${npm_config_cache:-$DATA_DIR/npm-cache}"
export UV_CACHE_DIR="${UV_CACHE_DIR:-$DATA_DIR/uv-cache}"
export npm_config_update_notifier=false

BASE="http://127.0.0.1:${PORT}"
# The server (and any STDIO MCP server it starts) doesn't get the two tokens.
env -u MCPJUNGLE_ADMIN_TOKEN -u MCPJUNGLE_CLIENT_TOKEN /mcpjungle start &
PID=$!

on_term() { log "stopping"; kill -TERM "$PID" 2>/dev/null; wait "$PID"; exit 0; }
trap on_term TERM INT

# Wait for the HTTP server (migrations run before it listens).
for i in $(seq 1 120); do
  kill -0 "$PID" 2>/dev/null || { wait "$PID"; rc=$?; die "mcpjungle exited during startup (code $rc)"; }
  curl -fsS -o /dev/null "$BASE/health" && break
  sleep 1
done
curl -fsS -o /dev/null "$BASE/health" || { kill "$PID"; die "mcpjungle did not answer /health within 120 s"; }

api() { # api METHOD PATH TOKEN [JSON]  -> prints body, then the HTTP code on the last line
  local m=$1 p=$2 t=$3 d=${4:-}
  if [ -n "$d" ]; then
    curl -sS -X "$m" -H "Authorization: Bearer $t" -H 'Content-Type: application/json' -d "$d" -w '\n%{http_code}' "$BASE$p"
  else
    curl -sS -X "$m" -H "Authorization: Bearer $t" -w '\n%{http_code}' "$BASE$p"
  fi
}
code_of() { tail -n1 <<<"$1"; }

bootstrap() {
  # 1. Initialise in enterprise mode (only the very first boot succeeds).
  local r c tmp
  r=$(curl -sS -X POST -H 'Content-Type: application/json' -d '{"mode":"enterprise"}' -w '\n%{http_code}' "$BASE/init")
  c=$(code_of "$r")
  if [ "$c" = "200" ]; then
    tmp=$(head -n -1 <<<"$r" | sed -n 's/.*"admin_access_token":"\([^"]*\)".*/\1/p')
    [ -n "$tmp" ] || { log "init returned no admin token"; return 1; }
    # Replace the random admin token with MCPJUNGLE_ADMIN_TOKEN.
    r=$(api PUT /api/v0/users/admin "$tmp" "{\"username\":\"admin\",\"access_token\":\"$ADMIN_TOKEN\"}")
    [ "$(code_of "$r")" = "200" ] || { log "could not set the admin token (HTTP $(code_of "$r"))"; return 1; }
    log "server initialised in enterprise mode; admin token set from MCPJUNGLE_ADMIN_TOKEN"
  else
    log "server already initialised"
  fi

  # 2. Check the admin token works.
  r=$(api GET /api/v0/users/whoami "$ADMIN_TOKEN")
  if [ "$(code_of "$r")" != "200" ]; then
    log "WARNING: MCPJUNGLE_ADMIN_TOKEN is not accepted by this server."
    log "If you changed it, first rotate it with: mcpjungle update user admin --access-token <new> (using the old token)."
    return 2
  fi

  # 3. Create or update the default MCP client (allowed to use every registered server).
  r=$(api GET /api/v0/clients "$ADMIN_TOKEN")
  [ "$(code_of "$r")" = "200" ] || { log "could not list MCP clients (HTTP $(code_of "$r"))"; return 1; }
  if grep -q "\"name\":\"$CLIENT_NAME\"" <<<"$r"; then
    r=$(api PUT "/api/v0/clients/$CLIENT_NAME" "$ADMIN_TOKEN" "{\"access_token\":\"$CLIENT_TOKEN\"}")
    [ "$(code_of "$r")" = "200" ] || { log "could not update MCP client '$CLIENT_NAME' (HTTP $(code_of "$r"))"; return 1; }
    log "MCP client '$CLIENT_NAME' token synced from MCPJUNGLE_CLIENT_TOKEN"
  else
    r=$(api POST /api/v0/clients "$ADMIN_TOKEN" "{\"name\":\"$CLIENT_NAME\",\"description\":\"Created by the Railway template; can use every registered MCP server\",\"allow_list\":[\"*\"],\"access_token\":\"$CLIENT_TOKEN\"}")
    [ "$(code_of "$r")" = "201" ] || { log "could not create MCP client '$CLIENT_NAME' (HTTP $(code_of "$r"))"; return 1; }
    log "MCP client '$CLIENT_NAME' created (token = MCPJUNGLE_CLIENT_TOKEN)"
  fi
  return 0
}

# Retried, because a parallel first deploy can be initialising the same database.
ok=1
for i in 1 2 3 4 5 6; do
  bootstrap; ok=$?
  [ $ok -ne 1 ] && break
  sleep 5
done
# A wrong admin token (ok=2) keeps the gateway up with a warning; any other failure restarts.
[ $ok -eq 1 ] && { kill "$PID"; die "first-boot setup failed"; }

# CLI config inside the container, for `railway ssh` then `mcpjungle list servers`.
if [ $ok -eq 0 ]; then
  umask 077
  printf 'registry_url: %s\naccess_token: %s\n' "$BASE" "$ADMIN_TOKEN" > "${HOME:-/root}/.mcpjungle.conf" 2>/dev/null || true
fi
log "ready: MCP endpoint /mcp (Streamable HTTP), /sse (SSE), health /health"

wait "$PID"; rc=$?
# Railway's ON_FAILURE policy restarts only on a non-zero exit.
[ $rc -eq 0 ] && rc=1
log "mcpjungle exited unexpectedly (code $rc)"
exit $rc
